        uint256 newBal = c.balances(sender);
        assert(newBal == prevBal);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address user, uint amount) public payable {
        require(amount >= 1 ether);
        uint balBefore = c.balances(user);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));
        require(success);
        uint balAfter = c.balances(user);
        assert(balAfter >= balBefore + amount);
    }

    receive() external payable {}
}

